          recall += v.recall;
          ndcg += v.ndcg;
          ap += v.ap;
          rr += v.rr;
        }
        lines.add(
          '  ${rankings[m]} precision ${real(hits / (cutoff * count))} recall ${real(recall / count)} ndcg ${real(ndcg / count)} map ${real(ap / count)} mrr ${real(rr / count)} hit_rate ${real(hitUsers / count)}',
