          fields = ['group ${g + 1} users ${groups[g].length}'];
      for (var m = 0; m < 7; m++) {
        var mean = double.nan;
        if (users.isNotEmpty) {
          var total = 0.0;
          for (final u in users) {
            total += userRankingMetrics(m, u, size).ndcg;
          }
